            title: '识别：6信号判断TA是不是"傲慢型"',
            instruction: '看6个信号：①打断你说话；②纠正你的每个细节；③用居高临下的语气；④从不承认自己错了；⑤贬低别人的成就；⑥只跟TA认为"比自己差"的人交往对强者谄媚对弱者傲慢。命中3条以上=傲慢型。同时区分"傲慢"和"自信"——自信的人不否定别人能听意见能认错。',
            example: 'TA打断你说话——信号1。TA说"不是10点是10点03分"鸡毛蒜皮都要纠正——信号2。TA说"这个你都不懂？""让我来教你"——信号3。TA被证明错了也说"那是特殊情况"——信号4。TA说"那个有什么难的"贬低别人成就——信号5。',
            tip: '识别后理解一点：傲慢往往是深层自卑的盔甲——TA必须踩低别人才能感觉自己有价值。理解这一点不是为了同情TA，而是为了不被TA激怒——TA的话伤不到你了。',
            keywords: ['6信号', '3条以上', '深层自卑'],
