            title: '法则1：不争论——微笑点头然后按自己的想法做',
            instruction: '跟傲慢的人争论=你承认了TA有跟你争论的资格=你在TA的水平上被TA打败。TA说了一个你不同意的观点：微笑点头→然后按你自己的想法做。TA纠正你的细节："嗯，你观察得挺仔细"→不需要反驳。你赢了争论但输了关系（如果你需要这个关系），而且TA不会因为输了就尊重你。',
            example: 'TA："你这个想法不对，应该是..."你："嗯，你说的有道理。"（微笑点头）→然后按你自己的想法做。TA："不是10点是10点03分。"你："嗯，你观察得挺仔细。"（不需要反驳）。',
            tip: '不争论的核心：你不需要让TA认同你。你按自己的想法做+让结果说话=最高级的回应。争论=浪费时间+伤关系+赢不了。',
            keywords: ['不争论', '微笑点头', '按自己想法做'],
          ),
          KnowledgeGuideStep(
            step: 3,
            title: '法则2：不卑微——保持不卑不亢',
            instruction: '傲慢的人最会"踩软柿子"——你越卑微TA越踩你。不要用讨好来获得TA的认可："您说得对""您真厉害"——TA会觉得你确实不如TA。保持不卑不亢："你的观点我听到了，我有自己的考虑。"用平等的姿态交流——如果你做不到平等，就不要跟TA深交。',
            example: 'TA："让我来教你..."❌ 你："您真厉害，向您学习！"（卑微=被踩）。✅ 你："谢谢你的建议，我有自己的考虑。"（不卑不亢）。TA："这个你都不会？"❌ 你："是是是我笨。"（卑微）。✅ 你："这个我可能不熟，但我可以学。"（平等）。',
            tip: '不卑微的核心：你不比TA低。TA的傲慢是TA的问题不是你的问题。你不需要通过卑微讨好获得TA的认可——TA的认可不值得你失去尊严。',
            keywords: ['不卑微', '不卑不亢', '平等姿态'],
          ),
          KnowledgeGuideStep(
            step: 4,
            title: '法则3：用实力说话——结果是最好的回应',
            instruction: '傲慢的人只尊重一种人：比TA强的人。你跟TA说一万句不如做出一个TA做不到的结果。在你的专业领域展示能力：TA说"这个你不会吧"→你做出一个漂亮的成果→TA闭嘴了。不要急于证明自己——让结果替你说话。',
            example: 'TA："这个项目你能搞定吗？我看难。"→你不说"我能"你直接做出一个漂亮的成果。下次TA再说"这个你不会吧"时，自然有人替你说"上次那个项目就是TA做的"。TA闭嘴了。',
            tip: '用实力说话=最高级的回应。你不需要跟TA争，你做出TA做不到的事=TA自然闭嘴。这比一万句争辩都有效。同时不要急于证明自己——急=露怯=被TA看穿。让结果自然来。',
            keywords: ['用实力说话', '结果回应', '不急于证明'],
          ),
          KnowledgeGuideStep(
            step: 5,
