            instruction: '最佳策略：保持距离不深交。如果必须建立关系（工作需要）：①先展示你的实力/价值让TA觉得你"有资格"跟TA平等交流；②在TA擅长的领域真诚请教——傲慢的人最吃"被认可"这一套；③但不要过度恭维——TA会看不起你；④在你不认同的时候不争辩但也不附和；⑤用结果说话不用嘴说话。',
            example: '工作需要建立关系：先展示实力"上次那个case我做过类似的，可以参考一下我的经验"。在TA擅长领域请教"听说您在这个领域很厉害，我有个问题想请教"。不附和不争辩"您的观点我听到了，我有自己的考虑"。用结果说话——做出TA做不到的事。',
            tip: '傲慢的人只尊重强者。建立关系的方式不是讨好，是展示你的价值。同时保持距离——傲慢的人很难真心对待别人，TA的"关系"往往是"工具性的"。合作可以，深交不必。',
            keywords: ['保持距离', '展示实力', '真诚请教', '不深交'],
          ),
        ],
      ),
    ],
  ),

