        content: '阶段1相识期（建立好感展示价值）；阶段2熟悉期（找共同点建舒适感）；阶段3友谊期（建信任互相支持）；阶段4暧昧/恋人期（情感波动升级肢体接触）；阶段5稳定/磨合期（接受不完美建冲突解决机制）；阶段6猜忌期（信任动摇识别根源）；阶段7破裂期（评估可修复or止损）；阶段8修复期（重建信任解决根本问题）；阶段9终结期（体面结束自我疗愈）。',
