            instruction: '修复期：双方都愿意修复时进入。前提：双方意愿+真诚认错+给机会+根本问题可解决。四阶段：止血→沟通→重建→新平衡。终结期：关系无法修复或自然结束。核心任务：体面结束、自我疗愈、从中成长。断舍离5步：物理断联→情绪释放→理性复盘→重建自我→准备新开始。',
            example: '修复期：双方都还想挽救→止血期停止互相伤害→沟通期深度沟通→重建期用行动证明改变→新平衡期建立新相处模式。终结期：体面结束（诚实但不残忍）→物理断联→情绪释放→理性复盘→重建自我→3-6个月后准备新开始。',
            tip: '修复不是"和好"——和好只需要一句"对不起"，修复需要重建被破坏的信任系统。终结不是失败——结束一段已经没有生命力的关系，是比维持它更需要勇气的事。',
            keywords: ['修复重建', '体面结束', '断舍离5步'],
          ),
        ],
      ),
    ],
  ),

