  // ===================== K067 破裂期：关系崩塌的过程与止损 =====================
  'K067': KnowledgeExtensionBundle(
    knowledgeId: 'K067',
    keyPoints: const [
      KnowledgeKeyPoint(
        title: '关系破裂的4个阶段',
        content: '阶段1微裂痕期（可修复）：小摩擦越来越多，吵完还能和好但冷战时间变长。阶段2疏远期（修复难度增加）：不再吵架了但不是因为和好而是因为"懒得吵了"，情感上开始撤出。阶段3危机期（破裂临界点）：出现重大事件（出轨/严重谎言/激烈争吵说出分手），双方开始认真考虑"还要不要继续"。阶段4断裂期（实质破裂）：关系名存实亡，情感连接已断，开始想象没有TA的生活。',
        icon: Icons.timeline_rounded,
        importance: '核心',
      ),
      KnowledgeKeyPoint(
        title: '判断"该修复"还是"该止损"',
        content: '该修复（满足3条以上）：双方都还想挽救+破裂是沟通问题非原则问题+还有美好共同记忆+想到失去TA会心痛+愿意为修复付出努力+破裂是近期的事。该止损（满足2条以上）：一方已不想修复+破裂是原则问题（出轨/家暴/赌博/严重欺骗）+你跟TA在一起比独处更痛苦+TA没有重建信任的意愿和行动+你想象离开TA之后的生活觉得轻松+价值观根本分歧+TA反复犯同样的错误。',
        icon: Icons.balance_rounded,
        importance: '核心',
      ),
      KnowledgeKeyPoint(
        title: '止损3原则',
        content: '原则1止损不是失败是对自己负责（沉没成本谬误：过去的投入不应该影响未来的决策）；原则2止损要果断不要"温水煮青蛙"（决定了就走不要"分了又合合了又分"）；原则3止损后要断干净（至少初期不立刻做朋友+取关不看TA动态+不联系3-6个月）。',
        icon: Icons.exit_to_app_rounded,
        importance: '核心',
      ),
      KnowledgeKeyPoint(
        title: '被出轨后的处理5步',
        content: '①第一时间不要做任何决定（不要立刻分手也不要立刻原谅）；②收集证据（不是为了报复是为了你自己不被TA的"否认"搞混判断）；③评估TA的态度（真诚悔改vs找借口推卸责任）；④如果决定修复设定明确条件和时间线（不是"我改"就完了）；⑤如果决定离开不要问"为什么"（没有答案能让你释怀，离开本身就是答案）。',
        icon: Icons.healing_rounded,
        importance: '极重要',
      ),
      KnowledgeKeyPoint(
        title: '疏远期是最危险的信号',
        content: '不吵架=不在乎了=心已经走了。吵架说明还在乎（虽然方式不对），不吵架说明已经放弃。如果你们从"经常吵架"变成"不再吵架"——不是因为和好了而是因为懒得吵了——这是关系走向终结的最强信号。如果你还想挽救，疏远期是用力的最后时机。',
        icon: Icons.warning_amber_rounded,
        importance: '重要',
      ),
    ],
    practices: const [
      KnowledgePractice(
